function hashString(s){ var h=0; for(var i=0;i<s.length;i++){ h=(Math.imul(h,31)+s.charCodeAt(i))>>>0; } return h>>>0; }
function avatarText(name, opts){
  opts=opts||{};
  var n=String(name||'').trim();
  var initial = n ? n.charAt(0).toUpperCase() : '?';
  var seed=opts.seed!=null?opts.seed:hashString(n||'guest');
  var hue=seed%360;
  var size=opts.size!=null?opts.size:96;
  var round=opts.round!==false;
  return {ok:true, initial:initial, hue:hue, size:size, seed:seed,
          bg:'hsl('+hue+',62%,52%)', fg:'#ffffff',
          radius: round?'50%':'12px',
          fontSize: Math.round(size*(n.length>1?0.42:0.46))};
}

var EXPORTS={avatarText:avatarText,hashString:hashString};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AvatarTextForgePure = EXPORTS; }
